package com.nexusdrive.metadata.config;import com.nexusdrive.common.config.JwtProperties;import com.nexusdrive.common.security.*;import org.springframework.context.annotation.*;import org.springframework.scheduling.annotation.*;import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.web.SecurityFilterChain;import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;@Configuration@EnableMethodSecurity@EnableAsync@EnableScheduling public class SecurityConfig{@Bean JwtTokenProvider jwt(JwtProperties p){return new JwtTokenProvider(p);}@Bean JwtAuthFilter filter(JwtTokenProvider j){return new JwtAuthFilter(j);}@Bean SecurityFilterChain chain(HttpSecurity h,JwtAuthFilter f)throws Exception{return h.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/actuator/health","/swagger-ui/**","/swagger-ui.html","/v3/api-docs/**").permitAll().anyRequest().authenticated()).addFilterBefore(f,UsernamePasswordAuthenticationFilter.class).build();}}
